using System;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public sealed class GridShiftCharacterEditor:MonoBehaviour {
 public static bool IsOpen{get;private set;}GridShiftCharacterData draft;Action<GridShiftCharacterData> apply;TMP_InputField nameField,age,pronouns,origin,bio;TMP_Text modelLabel,skinLabel,outfitLabel,status;GameObject preview;Camera camera;RenderTexture texture;RawImage portrait;ScrollRect fieldsScroll;PlayerMovement player;bool blocked;CursorLockMode cursor;bool visible;GridShiftDialogueVisibility hidden;
 public static void Open(GridShiftCharacterData data,Action<GridShiftCharacterData> onApply){if(IsOpen)return;var go=new GameObject("Character creation and wardrobe");var view=go.AddComponent<GridShiftCharacterEditor>();view.draft=GridShiftCharacter.Normalize(data);if(view.draft.model<0)view.draft.model=0;view.apply=onApply;view.Build();}
 void Build(){IsOpen=true;player=DeliveryManager.Instance!=null?InteractionFocus.PlayerFor(DeliveryManager.Instance):null;blocked=player!=null&&player.ControlsBlocked;if(player!=null){player.BlockControls(true);hidden=new GridShiftDialogueVisibility(player);}cursor=Cursor.lockState;visible=Cursor.visible;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;var canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=970;gameObject.AddComponent<GraphicRaycaster>();var scale=gameObject.AddComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1920,1080);scale.matchWidthOrHeight=.5f;var shade=GridShiftUI.Rect("Character backdrop",transform,Vector2.zero);GridShiftUI.Stretch(shade,Vector2.zero,Vector2.zero);shade.gameObject.AddComponent<Image>().color=new Color(.015f,.025f,.045f,.97f);
  var panel=GridShiftUI.Rect("Character editor",shade,new Vector2(1700,950));GridShiftDialogueStyle.Surface(panel.gameObject.AddComponent<Image>());GridShiftDialogueStyle.Brand(panel);var title=GridShiftUI.Text(panel,"SEU PERSONAGEM",32,60);title.rectTransform.anchoredPosition=new Vector2(-160,410);var content=GridShiftUI.Scroll(panel,new Vector2(35,110),new Vector2(-590,-175),out fieldsScroll);
  var identity=GridShiftUI.Button(panel,"Identidade",()=>{fieldsScroll.StopMovement();fieldsScroll.verticalNormalizedPosition=1;},46);identity.GetComponent<RectTransform>().sizeDelta=new Vector2(420,46);identity.GetComponent<RectTransform>().anchoredPosition=new Vector2(-460,340);var appearance=GridShiftUI.Button(panel,"Visual e cores",()=>{fieldsScroll.StopMovement();fieldsScroll.verticalNormalizedPosition=0;},46);appearance.GetComponent<RectTransform>().sizeDelta=new Vector2(420,46);appearance.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,340);
  nameField=GridShiftUI.Input(content,"Nome do personagem");nameField.characterLimit=40;nameField.text=draft.name;age=GridShiftUI.Input(content,"Idade (1 a 120)");age.characterLimit=3;age.contentType=TMP_InputField.ContentType.IntegerNumber;age.text=draft.age.ToString();pronouns=GridShiftUI.Input(content,"Pronomes / apresentação (opcional)");pronouns.characterLimit=32;pronouns.text=draft.pronouns;origin=GridShiftUI.Input(content,"Cidade de origem (opcional)");origin.characterLimit=64;origin.text=draft.origin;bio=GridShiftUI.Input(content,"História e personalidade (opcional)");bio.characterLimit=600;bio.lineType=TMP_InputField.LineType.MultiLineNewline;bio.text=draft.biography;bio.GetComponent<RectTransform>().sizeDelta=new Vector2(700,110);
  modelLabel=GridShiftUI.Text(content,"",24,38);GridShiftUI.Button(content,"Visual anterior",()=>CycleModel(-1));GridShiftUI.Button(content,"Próximo visual / roupa",()=>CycleModel(1));skinLabel=GridShiftUI.Text(content,"",23,38);GridShiftUI.Button(content,"Alternar tom de pele",()=>{draft.skin=(draft.skin+2)%(GridShiftCharacter.SkinColors.Length+1)-1;RebuildPreview();});outfitLabel=GridShiftUI.Text(content,"",23,38);GridShiftUI.Button(content,"Alternar cor da roupa",()=>{draft.outfit=(draft.outfit+2)%(GridShiftCharacter.OutfitColors.Length+1)-1;RebuildPreview();});
  var previewRect=GridShiftUI.Rect("Character preview",panel,new Vector2(475,690));previewRect.anchorMin=previewRect.anchorMax=new Vector2(1,.5f);previewRect.pivot=new Vector2(1,.5f);previewRect.anchoredPosition=new Vector2(-40,25);portrait=previewRect.gameObject.AddComponent<RawImage>();portrait.color=Color.white;var rotate=GridShiftUI.Button(panel,"Girar personagem",()=>{if(preview!=null)preview.transform.Rotate(0,45,0);},48);rotate.GetComponent<RectTransform>().anchoredPosition=new Vector2(565,-365);rotate.GetComponent<RectTransform>().sizeDelta=new Vector2(450,48);
  var save=GridShiftUI.Button(panel,"Aplicar personagem",Confirm,55,true);save.GetComponent<RectTransform>().sizeDelta=new Vector2(430,55);save.GetComponent<RectTransform>().anchoredPosition=new Vector2(-230,-425);var cancel=GridShiftUI.Button(panel,"Cancelar",Close,55);cancel.GetComponent<RectTransform>().sizeDelta=new Vector2(430,55);cancel.GetComponent<RectTransform>().anchoredPosition=new Vector2(230,-425);status=GridShiftUI.Text(panel,"Prévia do modelo e das cores; alterações ficam neste save.",18,38);status.rectTransform.sizeDelta=new Vector2(1000,38);status.rectTransform.anchoredPosition=new Vector2(-245,-365);
  texture=new RenderTexture(512,768,24);portrait.texture=texture;var cam=new GameObject("Character preview camera");camera=cam.AddComponent<Camera>();camera.enabled=false;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.035f,.085f,.13f);camera.cullingMask=1<<15;camera.targetTexture=texture;camera.fieldOfView=28;var lamp=new GameObject("Preview soft light");lamp.transform.SetParent(cam.transform,false);lamp.transform.position=new Vector3(2,5003,-2);var light=lamp.AddComponent<Light>();light.type=LightType.Point;light.range=9;light.intensity=4;light.cullingMask=1<<15;light.shadows=LightShadows.None;RebuildPreview();
 }
 void CycleModel(int delta){var catalog=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");int count=catalog!=null?catalog.models.Length:0;if(count==0){status.text="Catálogo de aparência não disponível.";return;}draft.model=(draft.model+delta+count)%count;RebuildPreview();}
 void RebuildPreview(){var catalog=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");if(preview!=null){preview.SetActive(false);Destroy(preview);}if(catalog==null||catalog.models.Length==0){status.text="Catálogo de aparência não disponível.";return;}draft.model=Mathf.Clamp(draft.model,0,catalog.models.Length-1);preview=Instantiate(catalog.models[draft.model]);preview.name="Isolated avatar preview";preview.transform.SetPositionAndRotation(new Vector3(0,5000,0),Quaternion.Euler(0,180,0));foreach(var t in preview.GetComponentsInChildren<Transform>(true))t.gameObject.layer=15;foreach(var c in preview.GetComponentsInChildren<Collider>())c.enabled=false;GridShiftPlayerAppearance.ApplyColors(preview,draft);camera.transform.position=preview.transform.position+new Vector3(0,1.05f,-4.8f);camera.transform.LookAt(preview.transform.position+Vector3.up*.95f);modelLabel.text="Visual "+(draft.model+1)+" / "+catalog.models.Length;skinLabel.text="Pele: "+(draft.skin<0?"original":"tom "+(draft.skin+1));outfitLabel.text="Roupa: "+(draft.outfit<0?"original":"cor "+(draft.outfit+1));}
 void LateUpdate(){if(camera!=null&&preview!=null)camera.Render();}
 void Update(){if(GridShiftControls.Back){GridShiftControls.SuppressFrame();Close();}}
 void Confirm(){if(string.IsNullOrWhiteSpace(nameField.text)){status.text="Dê um nome ao personagem.";return;}if(!int.TryParse(age.text,out int number)||number<1||number>120){status.text="Informe uma idade entre 1 e 120.";return;}draft.name=nameField.text;draft.age=number;draft.pronouns=pronouns.text;draft.origin=origin.text;draft.biography=bio.text;var result=GridShiftCharacter.Normalize(draft);var callback=apply;Close();callback?.Invoke(result);}
 public void Close(){if(!IsOpen)return;IsOpen=false;hidden?.Restore();hidden=null;if(player!=null)player.BlockControls(blocked);Cursor.lockState=cursor;Cursor.visible=visible;GridShiftControls.SuppressFrame();Destroy(gameObject);}
 void OnDestroy(){if(IsOpen){IsOpen=false;hidden?.Restore();if(player!=null)player.BlockControls(blocked);Cursor.lockState=cursor;Cursor.visible=visible;}if(preview!=null)Destroy(preview);if(camera!=null)Destroy(camera.gameObject);if(texture!=null){texture.Release();Destroy(texture);}}
}
